39	// DispatchInboxEmail sends the email notification for an inbox entry when configured.
40	func (d *EmailDispatcher) DispatchInboxEmail(ctx context.Context, inbox *store.Inbox) error {
41		if inbox == nil || inbox.Message == nil {
42			return nil
43		}
44	
45		setting, err := d.store.GetInstanceNotificationSetting(ctx)
46		if err != nil {
47			return errors.Wrap(err, "failed to get notification setting")
48		}
49		emailSetting := setting.GetEmail()
50		if emailSetting == nil || !emailSetting.Enabled {
51			return nil
52		}
53		if d.baseURL() == "" {
54			slog.Warn("Skipping inbox email notification because instance URL is required",
55				slog.Int64("inbox_id", int64(inbox.ID)),
56				slog.Int64("receiver_id", int64(inbox.ReceiverID)))
57			return nil
58		}
59	
60		receiver, err := d.store.GetUser(ctx, &store.FindUser{ID: &inbox.ReceiverID})
61		if err != nil {
62			return errors.Wrap(err, "failed to get notification receiver")
63		}
64		if receiver == nil || strings.TrimSpace(receiver.Email) == "" {
65			return nil
66		}
67	
68		sender, err := d.store.GetUser(ctx, &store.FindUser{ID: &inbox.SenderID})
69		if err != nil {
70			return errors.Wrap(err, "failed to get notification sender")
71		}
72		if sender == nil {
73			return nil
74		}
75	
76		memosByID, err := d.listMemosByID(ctx, collectInboxMemoIDs([]*store.Inbox{inbox}))
77		if err != nil {
78			return errors.Wrap(err, "failed to get notification memos")
79		}
80	
81		message, err := d.buildInboxEmailMessage(inbox, receiver, sender, memosByID)
82		if err != nil {
83			return err
84		}
85		if message == nil {
86			return nil
87		}
88		message.ReplyTo = emailSetting.ReplyTo
89	
90		config := EmailConfigFromInstanceSetting(emailSetting)
91		if err := config.Validate(); err != nil {
92			return errors.Wrap(err, "invalid notification email setting")
93		}
94	
95		d.sender(config, message)
96		return nil
97	}
